package com.ecommerce.cart.service; import jakarta.persistence.*; import java.math.*; import java.util.*; @Entity @Table(name="cart_items",uniqueConstraints=@UniqueConstraint(name="uk_cart_product",columnNames={"customer_id","product_id"})) public class CartItem { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID customerId; @Column(nullable=false) UUID productId; @Column(nullable=false) int quantity; @Column(nullable=false,precision=14,scale=2) BigDecimal unitPrice; public UUID getId(){return id;} public UUID getCustomerId(){return customerId;} public void setCustomerId(UUID v){customerId=v;} public UUID getProductId(){return productId;} public void setProductId(UUID v){productId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} }